package frc.robot;

import edu.wpi.first.math.geometry.Translation3d;
import frc.lib.visualization.ComponentPoses;

/**
 * Moving parts of the robot's 3D model in AdvantageScope. Generated by 3161
 * Robot Setup from .robot-setup/cad.json -- change it in the app's CAD tab;
 * edits here are overwritten.
 *
 * In AdvantageScope: 3D Field, robot model "3161 Rebuilt2026 FIXED", drag the robot
 * pose onto the field and "RobotComponents" onto it as Components.
 * Points are meters in the robot frame (X forward, Y left, Z up, from the
 * robot's center on the floor).
 */
public final class RobotComponents {
    private RobotComponents() {
    }

    public static ComponentPoses start(RobotContainer robot) {
        ComponentPoses poses = new ComponentPoses("RobotComponents");
        // model_0.glb: "3161-26-A-0700 <1>" -> Turret / Turret (hand-written)
        int turret = poses.pivot(ComponentPoses.ROBOT, () -> robot.turret.getTurretModelPosition(), 0.0, new Translation3d(-0.1674, -0.1463, 0.479), new Translation3d(0.0, 0.0, 1.0));
        // model_1.glb: "Kicker <1>" -> Kicker/Kicker
        int kicker = poses.pivot(ComponentPoses.ROBOT, ComponentPoses.mechanism("Kicker/Kicker"), 0.0, new Translation3d(0.31889, -0.13125, 0.14702), new Translation3d(0.0, 1.0, 0.0));
        // model_2.glb: "Frame Subssembly <1>" -> Intake / Intake Extension (hand-written)
        int intakeExtension = poses.slide(ComponentPoses.ROBOT, () -> robot.intake.getIntakeExtensionPosition() * 0.0254, 0.0, new Translation3d(0.994522, 0.0, -0.104528));
        return poses;
    }
}
